-- Perguntas do diagnóstico em português (interface pt). As colunas originais continuam em espanhol.
alter table public.perguntas add column if not exists "perguntaPt" text;
alter table public.perguntas add column if not exists "opcoesRespostaPt" jsonb;

update public.perguntas set "perguntaPt" = 'A empresa identifica quais atividades geram emissões de gases de efeito estufa (uso de eletricidade, combustíveis, transporte)?', "opcoesRespostaPt" = '[{"label": "Sim, e as mede periodicamente (pegada de carbono)", "valor": 4}, {"label": "Sim, identifica, mas não mede", "valor": 3}, {"label": "Tem só uma ideia geral", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_amb_01';
update public.perguntas set "perguntaPt" = 'A empresa aplica medidas para reduzir as emissões de transporte e deslocamentos (rotas eficientes, veículos menos poluentes, reuniões virtuais)?', "opcoesRespostaPt" = '[{"label": "Sim, de forma permanente", "valor": 4}, {"label": "Aplica algumas medidas", "valor": 3}, {"label": "Já avaliou, mas não aplicou", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_amb_02';
update public.perguntas set "perguntaPt" = 'Como a empresa gerencia seu consumo de eletricidade?', "opcoesRespostaPt" = '[{"label": "Mede todo mês, tem metas de economia e usa ou avalia energias renováveis", "valor": 4}, {"label": "Revisa as contas e aplica medidas básicas de economia", "valor": 3}, {"label": "Só confere o valor a pagar", "valor": 2}, {"label": "Não tem nenhum controle / Não sabe", "valor": 1}]'::jsonb where id = 'q_amb_03';
update public.perguntas set "perguntaPt" = 'Como a empresa gerencia seu consumo de água?', "opcoesRespostaPt" = '[{"label": "Mede, tem metas de economia e conserta vazamentos de forma preventiva", "valor": 4}, {"label": "Revisa as contas e aplica medidas básicas de economia", "valor": 3}, {"label": "Só age quando detecta um problema", "valor": 2}, {"label": "Não tem nenhum controle / Não sabe", "valor": 1}]'::jsonb where id = 'q_amb_04';
update public.perguntas set "perguntaPt" = 'O que a empresa faz com os resíduos que gera?', "opcoesRespostaPt" = '[{"label": "Reduz, separa e entrega para reciclagem ou a um gestor autorizado, com registro", "valor": 4}, {"label": "Separa alguns resíduos para reciclagem", "valor": 3}, {"label": "Tenta reduzir, mas não separa", "valor": 2}, {"label": "Não gerencia: tudo vai para o lixo comum", "valor": 1}]'::jsonb where id = 'q_amb_05';
update public.perguntas set "perguntaPt" = 'A empresa sabe se a Lei REP (Lei 20.920 do Chile) se aplica a ela e cumpre as obrigações correspondentes?', "opcoesRespostaPt" = '[{"label": "Sim: verificou se se aplica e cumpre suas obrigações (ou confirmou que não se aplica)", "valor": 4}, {"label": "Conhece a lei, mas não verificou se se aplica", "valor": 3}, {"label": "Já ouviu falar dela", "valor": 2}, {"label": "Não conhece", "valor": 1}]'::jsonb where id = 'q_amb_06';
update public.perguntas set "perguntaPt" = 'A empresa usa materiais ou insumos reciclados, reutilizáveis, biodegradáveis ou de menor impacto ambiental?', "opcoesRespostaPt" = '[{"label": "Sempre que possível, com critérios definidos para escolhê-los", "valor": 4}, {"label": "Com frequência", "valor": 3}, {"label": "Ocasionalmente", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_amb_07';
update public.perguntas set "perguntaPt" = 'A empresa sabe como suas atividades podem afetar a flora, a fauna e os ecossistemas do entorno, e toma medidas para protegê-los?', "opcoesRespostaPt" = '[{"label": "Sim, toma medidas e participa de atividades de proteção ou recuperação de ecossistemas", "valor": 4}, {"label": "Conhece os impactos e toma algumas medidas", "valor": 3}, {"label": "Conhece os impactos, mas não toma medidas", "valor": 2}, {"label": "Não considerou isso", "valor": 1}]'::jsonb where id = 'q_amb_08';
update public.perguntas set "perguntaPt" = 'A empresa identifica os riscos do trabalho e aplica medidas de prevenção e segurança?', "opcoesRespostaPt" = '[{"label": "Tem procedimentos documentados, capacita e os revisa periodicamente", "valor": 4}, {"label": "Aplica medidas básicas de segurança", "valor": 3}, {"label": "Só age quando ocorre um acidente ou problema", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_soc_01';
update public.perguntas set "perguntaPt" = 'A empresa promove o bem-estar e o respeito no trabalho, e tem um procedimento para prevenir e tratar o assédio no trabalho?', "opcoesRespostaPt" = '[{"label": "Sim, com um protocolo conhecido por todos os trabalhadores e ações de bem-estar", "valor": 4}, {"label": "Tem um procedimento, mas ele não foi bem divulgado", "valor": 3}, {"label": "Trata de maneira informal, caso a caso", "valor": 2}, {"label": "Não", "valor": 1}]'::jsonb where id = 'q_soc_02';
update public.perguntas set "perguntaPt" = 'A empresa cumpre suas obrigações trabalhistas (contratos por escrito, pagamento de contribuições, jornada e descansos)?', "opcoesRespostaPt" = '[{"label": "Sempre, e revisa isso periodicamente", "valor": 4}, {"label": "Quase sempre", "valor": 3}, {"label": "Parcialmente", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_soc_03';
update public.perguntas set "perguntaPt" = 'A empresa aplica critérios de igualdade de oportunidades e não discriminação na contratação, na remuneração e nas promoções?', "opcoesRespostaPt" = '[{"label": "Sim, com critérios definidos e comunicados", "valor": 4}, {"label": "Na maioria dos casos, mas sem critérios escritos", "valor": 3}, {"label": "Ocasionalmente", "valor": 2}, {"label": "Não considerou isso", "valor": 1}]'::jsonb where id = 'q_soc_04';
update public.perguntas set "perguntaPt" = 'A empresa mantém boas relações com a comunidade onde atua (ouve os vizinhos, prefere fornecedores locais, considera o impacto das suas atividades)?', "opcoesRespostaPt" = '[{"label": "Sim, de forma ativa e permanente", "valor": 4}, {"label": "Com frequência", "valor": 3}, {"label": "Ocasionalmente", "valor": 2}, {"label": "Não considerou isso", "valor": 1}]'::jsonb where id = 'q_soc_05';
update public.perguntas set "perguntaPt" = 'A empresa participa ou apoia iniciativas que beneficiam a comunidade (voluntariado, doações, parcerias com organizações locais)?', "opcoesRespostaPt" = '[{"label": "Regularmente, com atividades planejadas", "valor": 4}, {"label": "Algumas vezes por ano", "valor": 3}, {"label": "Raramente", "valor": 2}, {"label": "Nunca", "valor": 1}]'::jsonb where id = 'q_soc_06';
update public.perguntas set "perguntaPt" = 'A empresa capacita seus trabalhadores?', "opcoesRespostaPt" = '[{"label": "Tem um plano anual de capacitação para todos os trabalhadores", "valor": 4}, {"label": "Capacita de forma ocasional", "valor": 3}, {"label": "Só faz uma integração na entrada", "valor": 2}, {"label": "Não capacita", "valor": 1}]'::jsonb where id = 'q_soc_07';
update public.perguntas set "perguntaPt" = 'A empresa avalia a rentabilidade do negócio e considera os custos e benefícios das suas iniciativas de sustentabilidade?', "opcoesRespostaPt" = '[{"label": "Sim, analisa seus resultados periodicamente e inclui o efeito das iniciativas sustentáveis", "valor": 4}, {"label": "Analisa a rentabilidade, mas não a relaciona com a sustentabilidade", "valor": 3}, {"label": "Revisa os resultados só no fim do ano", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_eco_01';
update public.perguntas set "perguntaPt" = 'A empresa registra e controla seus gastos para evitar perdas e desperdícios?', "opcoesRespostaPt" = '[{"label": "Tem um orçamento mensal e o compara com os resultados reais", "valor": 4}, {"label": "Registra os gastos, mas não tem orçamento", "valor": 3}, {"label": "Tem um controle informal", "valor": 2}, {"label": "Não controla seus gastos", "valor": 1}]'::jsonb where id = 'q_eco_02';
update public.perguntas set "perguntaPt" = 'A empresa investe em tecnologias ou melhorias de processos que aumentem sua eficiência e reduzam seus impactos (equipamentos eficientes, digitalização, processos mais limpos)?', "opcoesRespostaPt" = '[{"label": "Sim, de forma planejada e periódica", "valor": 4}, {"label": "Já fez alguns investimentos", "valor": 3}, {"label": "Já avaliou, mas não investiu", "valor": 2}, {"label": "Não considerou isso", "valor": 1}]'::jsonb where id = 'q_eco_03';
update public.perguntas set "perguntaPt" = 'A empresa desenvolve iniciativas que geram benefícios tanto para o negócio quanto para seus trabalhadores, clientes, fornecedores e comunidade?', "opcoesRespostaPt" = '[{"label": "Sim, fazem parte da sua estratégia", "valor": 4}, {"label": "Tem algumas iniciativas", "valor": 3}, {"label": "Ocasionalmente", "valor": 2}, {"label": "Não considerou isso", "valor": 1}]'::jsonb where id = 'q_eco_04';
update public.perguntas set "perguntaPt" = 'A empresa mantém registros financeiros organizados e dá informações claras a sócios, trabalhadores ou outros interessados quando necessário?', "opcoesRespostaPt" = '[{"label": "Sim, com registros em dia e relatórios periódicos", "valor": 4}, {"label": "Tem registros organizados, mas raramente os comunica", "valor": 3}, {"label": "Seus registros estão incompletos", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_eco_05';
update public.perguntas set "perguntaPt" = 'A empresa tem regras claras para a tomada de decisões e para prevenir conflitos de interesse e práticas desonestas?', "opcoesRespostaPt" = '[{"label": "Sim, por escrito (por exemplo, um código de ética) e conhecidas por todos", "valor": 4}, {"label": "Existem, mas de maneira informal", "valor": 3}, {"label": "Resolve caso a caso", "valor": 2}, {"label": "Não", "valor": 1}]'::jsonb where id = 'q_eco_06';
update public.perguntas set "perguntaPt" = 'A empresa mantém em dia suas obrigações legais (licenças, impostos, normas) e tem um canal para receber e resolver reclamações?', "opcoesRespostaPt" = '[{"label": "Sim, as duas coisas, com acompanhamento das reclamações", "valor": 4}, {"label": "Cumpre suas obrigações, mas não tem um canal de reclamações", "valor": 3}, {"label": "Cumpre parcialmente", "valor": 2}, {"label": "Não / Não sabe", "valor": 1}]'::jsonb where id = 'q_eco_07';
